# 更新标签配置预览时的默认样式 by lilong 240419
UPDATE bmos_platform.bp_tag_define SET preview_html = '<div
  style="
    width: 560px;
    height: 320px;
    box-sizing: border-box;
    padding: 25px 25px;
    background-color: #f8f8f8;
    border: 1px solid #e1e1e1;
    border-radius: 10px;
    overflow: hidden;
    display: flex;
    justify-content: center;
    align-items: center;
  "
>
  <div style="font-size: 20px; font-weight: normal; width: 100%; line-height: 30px;display: flex;justify-content: center;align-items: center;">
    <div
      style="
        float: left;
        width: 60%;
        display: grid;
        grid-template-rows: repeat(9, 1fr);
      "
    >
      <div id="field1"></div>
      <div id="field2"></div>
      <div id="field3"></div>
      <div id="field4"></div>
      <div id="field5"></div>
      <div id="field6"></div>
      <div id="field7"></div>
      <div id="field8"></div>
      <div id="field9"></div>
    </div>
    <div style="float: right; width: 40%;">
      <img
        width="100%"
        height="100%"
        src="data:image/png;base64,"
        alt=""
      />
    </div>
  </div>
</div>' WHERE id = 1;

